            className={b('item', {draggable: Boolean(dndProps)}, item.className)}
            onClick={item.onClick}
            data-qa={item.qa}
            {...dndProps}
            onDragStart={dndProps ? onDragStart : undefined}
            onDragEnd={dndProps ? onDragEnd : undefined}
