AAC,CAAC;QAC7C,CAAC;QACD,MAAA,IAAI,CAAC,SAAS,CAAC,GAAG,CAAC,SAAS,CAAC,0CAAE,GAAG,CAAC,OAAO,CAAC,CAAC;QAC5C,OAAO,GAAG,EAAE,CAAC,IAAI,CAAC,IAAI,CAAC,SAAS,EAAE,OAAO,CAAC,CAAC;IAC/C,CAAC;IAiBO,IAAI,CAA6B,SAAY,EAAE,OAA+B;QAClF,MAAM,QAAQ,GAAG,IAAI,CAAC,SAAS,CAAC,GAAG,CAAC,SAAS,CAAC,CAAC;QAC/C,IAAI,QAAQ,EAAE,CAAC;YACX,QAAQ,CAAC,MAAM,CAAC,OAAO,CAAC,CAAC;YACzB,IAAI,QAAQ,CAAC,IAAI,KAAK,CAAC,EAAE,CAAC;gBACtB,IAAI,CAAC,SAAS,CAAC,MAAM,CAAC,SAAS,CAAC,CAAC;YACrC,CAAC;QACL,CAAC;IACL,CAAC;;KAvBA,WAAW;AAtJL,oBAAY,GAAwB;IACvC,UAAU,EAAE,IAAI;IAChB,QAAQ,EAAE,IAAI;IACd,MAAM,EAAE,IAAI;IACZ,mBAAmB,EAAE,EAAE;IACvB,YAAY,EAAE,EAAE;IAChB,mBAAmB,EAAE,EAAE;IACvB,QAAQ,EAAE;QACN,kBAAkB,EAAE,CAAC;QACrB,aAAa,EAAE,KAAK;KACvB;IACD,OAAO,EAAE,EAAE;IACX,SAAS,EAAE,KAAK;IAChB,SAAS,EAAE,KAAK;CACnB,AAdkB,CAcjB;AAEK,mBAAW,GAAG,iBAAiB,AAApB,CAAqB","sourcesContent":["import React from 'react';

import noop from 'lodash/noop';
import pick from 'lodash/pick';

import {DEFAULT_GROUP, DEFAULT_NAMESPACE} from '../../constants';
import {DashKitDnDContext} from '../../context';
import type {
    Config,
    ConfigItem,
    ConfigLayout,
    GlobalParams,
    ItemDropProps,
    ItemsStateAndParams,
} from '../../shared';
import type {
    AddConfigItem,
    AddNewItemOptions,
    ContextProps,
    DashKitEventHandler,
    DashKitEventMap,
    DashKitEventName,
    DashKitGroup,
    GridReflowOptions,
    ItemManipulationCallback,
    MenuItem,
    Plugin,
    ReactGridLayoutProps,
    SetConfigItem,
    Settings,
    SettingsProps,
} from '../../typings';
import {RegisterManager, UpdateManager, reflowLayout} from '../../utils';
import {DashKitDnDWrapper} from '../DashKitDnDWrapper/DashKitDnDWrapper';
import DashKitView from '../DashKitView/DashKitView';
import GridLayout from '../GridLayout/GridLayout';
import type {OverlayControlItem, PreparedCopyItemOptions} from '../OverlayControls/OverlayControls';

interface DashKitGeneralProps {
    config: Config;
    editMode: boolean;
    draggableHandleClassName?: string;
    overlayControls?: Record<string, OverlayControlItem[]> | null;
    overlayMenuItems?: MenuItem[] | null;
}

interface DashKitDefaultProps {
    defaultGlobalParams: GlobalParams;
    globalParams: GlobalParams;
    itemsStateAndParams: ItemsStateAndParams;
    settings: SettingsProps;
    context: ContextProps;
    noOverlay: boolean;
    focusable?: boolean;
    groups?: DashKitGroup[];

    onItemEdit: (item: ConfigItem) => void;
    onChange: (data: {
        config: Config;
        itemsStateAndParams: ItemsStateAndParams;
        groups?: DashKitGroup[];
    }) => void;

    onDrop: (dropProps: ItemDropProps) => void;

    onItemMountChange?: (item: ConfigItem, state: {isAsync: boolean; isMounted: boolean}) => void;
    onItemRender?: (item: ConfigItem) => void;

    getPreparedCopyItemOptions?: (options: PreparedCopyItemOptions) => PreparedCopyItemOptions;
    onCopyFulfill?: (error: null | Error, data?: PreparedCopyItemOptions) => void;

    onItemFocus?: (item: ConfigItem) => void;
    onItemBlur?: (item: ConfigItem) => void;

    onDragStart?: ItemManipulationCallback;
    onDrag?: ItemManipulationCallback;
    onDragStop?: ItemManipulationCallback;
    onResizeStart?: ItemManipulationCallback;
    onResize?: ItemManipulationCallback;
    onResizeStop?: ItemManipulationCallback;
}

export interface DashKitProps extends DashKitGeneralProps, Partial<DashKitDefaultProps> {}

type DashKitInnerProps = DashKitGeneralProps & DashKitDefaultProps;

const registerManager = new RegisterManager();

/**
 * @internal Not part of the public API. Do not use in production code.
 * Module-scoped symbol — not accessible to external consumers holding a ref,
 * preventing synthetic event injection via instance._emit.
 */
export const _emitSymbol = Symbol('DashKit._emit');

const getReflowProps = (props: ReactGridLayoutProps): GridReflowOptions =>
    Object.assign(
        {compactType: 'vertical', cols: 36},
        pick(props, 'cols', 'maxRows', 'compactType'),
    );

const getReflowGroupsConfig = (groups: DashKitGroup[] = []) => {
    const defaultGridProps = getReflowProps(registerManager.gridLayout);

    return {
        defaultProps: defaultGridProps,
        groups: groups.reduce<Record<string, GridReflowOptions>>((memo, g) => {
            const groupId = g.id || DEFAULT_GROUP;
            memo[groupId] = g.gridProperties
                ? getReflowProps(g.gridProperties(defaultGridProps))
                : defaultGridProps;

            return memo;
        }, {}),
    };
};

export class DashKit extends React.PureComponent<DashKitInnerProps> {
    static defaultProps: DashKitDefaultProps = {
        onItemEdit: noop,
        onChange: noop,
        onDrop: noop,
        defaultGlobalParams: {},
        globalParams: {},
        itemsStateAndParams: {},
        settings: {
            autoupdateInterval: 0,
            silentLoading: false,
        },
        context: {},
        noOverlay: false,
        focusable: false,
    };

    static contextType = DashKitDnDContext;

    static registerPlugins(...plugins: Plugin[]) {
        plugins.forEach((plugin) => {
            registerManager.registerPlugin(plugin);
        });
    }

    static reloadPlugins(...plugins: Plugin[]) {
        plugins.forEach((plugin) => {
            registerManager.reloadPlugin(plugin);
        });
    }

    static setSettings(settings: Settings) {
        registerManager.setSettings(settings);
    }

    static setItem({
        item: setItem,
        namespace = DEFAULT_NAMESPACE,
        config,
        options = {},
        groups = [],
    }: {
        item: SetConfigItem;
        namespace?: string;
        config: Config;
        options?: Omit<AddNewItemOptions, 'reflowLayoutOptions'>;
        groups?: DashKitGroup[];
    }): Config {
        if (setItem.id) {
            return UpdateManager.editItem({
                item: setItem,
                namespace,
                config,
                options,
            });
        } else {
            const item = setItem as AddConfigItem;
            const registerManagerItem = registerManager.getItem(item.type);

            const layout = {...registerManagerItem.defaultLayout};

            const reflowLayoutOptions = getReflowGroupsConfig(groups);

            const copyItem = {...item};

            if (copyItem.layout) {
                Object.assign(layout, copyItem.layout);
                delete copyItem.layout;
            }

            return UpdateManager.addItem({
                item: copyItem,
                namespace,
                config,
                layout,
                options: {...options, reflowLayoutOptions},
            });
        }
    }

    static removeItem({
        id,
        config,
        itemsStateAndParams,
    }: {
        id: string;
        config: Config;
        itemsStateAndParams: ItemsStateAndParams;
    }): {config: Config; itemsStateAndParams: ItemsStateAndParams} {
        return UpdateManager.removeItem({id, config, itemsStateAndParams});
    }

    static reflowLayout({
        newLayoutItem,
        layout,
        groups,
    }: {
        newLayoutItem?: ConfigLayout;
        layout: ConfigLayout[];
        groups?: DashKitGroup[];
    }) {
        return reflowLayout({
            newLayoutItem,
            layout,
            reflowLayoutOptions: getReflowGroupsConfig(groups),
        });
    }

    metaRef = React.createRef<GridLayout>();

    private _handlers = new Map<string, Set<(...args: any[]) => void>>();

    render() {
        const content = (
            <DashKitView
                registerManager={registerManager}
                ref={this.metaRef}
                {...this.props}
                emitDashKitEvent={this[_emitSymbol]}
            />
        );

        if (!this.context && this.props.groups) {
            return <DashKitDnDWrapper>{content}</DashKitDnDWrapper>;
        }

        return content;
    }

    getItemsMeta() {
        return this.metaRef.current?.getItemsMeta() ?? [];
    }

    reloadItems(options?: {targetIds?: string[]; force?: boolean}) {
        this.metaRef.current?.reloadItems(options);
    }

    /**
     * @experimental This API can change in minor releases.
     * @param eventName Event name.
     * @param handler Event handler.
     * @returns Unsubscribe callback.
     */
    on<T extends DashKitEventName>(eventName: T, handler: DashKitEventHandler<T>): () => void {
        if (!this._handlers.has(eventName)) {
            this._handlers.set(eventName, new Set());
        }
        this._handlers.get(eventName)?.add(handler);
        return () => this._off(eventName, handler);
    }

    [_emitSymbol] = <T extends DashKitEventName>(eventName: T, event: DashKitEventMap[T]): void => {
        const handlers = this._handlers.get(eventName);
        if (!handlers) {
            return;
        }
        for (const handler of handlers) {
            try {
                (handler as DashKitEventHandler<T>)(event);
            } catch (e) {
                // eslint-disable-next-line no-console
                console.error('DashKit: event handler error', e);
            }
        }
    };

    private _off<T extends DashKitEventName>(eventName: T, handler: DashKitEventHandler<T>): void {
        const handlers = this._handlers.get(eventName);
        if (handlers) {
            handlers.delete(handler);
            if (handlers.size === 0) {
                this._handlers.delete(eventName);
            }
        }
    }
}
"]}
